        if ts.tzinfo is None:
            ts=ts.replace(tzinfo=datetime.timezone.utc)
        delta=now - ts
        seconds=int(delta.total_seconds())
        if seconds<60:
            return "now"
        if seconds<3600:
            mins=seconds//60
            return f"{{mins}} minutes ago" if mins!=1 else "a minute ago"
        if seconds<86400:
            hrs=seconds//3600
            return f"{{hrs}} hours ago" if hrs!=1 else "an hour ago"
        if seconds<86400*7:
            days=seconds//86400
            return f"{{days}} days ago" if days!=1 else "a day ago"
        if seconds<86400*30:
            weeks=seconds//(86400*7)
            return f"{{weeks}} weeks ago" if weeks!=1 else "a week ago"
        if seconds<86400*365:
            months=seconds//(86400*30)
            return f"{{months}} months ago" if months!=1 else "a month ago"
        years=seconds//(86400*365)
        return f"{{years}} years ago" if years!=1 else "a year ago"

